<?php

declare(strict_types=1);

/**
 * Exports a namespace-prefixed copy of the CREED reader for a consumer
 * package (PROCTOR, BOOSTER, ROLLCALL, ADVISOR) to carry under its own
 * namespace, so two tools in one app never fight over a class name.
 *
 * Usage:
 *   php bin/export.php --namespace=Waynestate\Proctor\Creed --to=<dir>
 *   php bin/export.php --check --namespace=Waynestate\Proctor\Creed --to=<dir>
 *
 * The export writes into <dir>:
 *   Policy.php, State.php  the reader, namespaced to the target, with a
 *                          "do not edit" header; Policy::bundled() is
 *                          repointed at the copy's own policy.json
 *   policy.json            byte-identical to policy/policy.json
 *   manifest.json          schema_version, source, creed_version, namespace,
 *                          and the sha256 of each exported file
 *
 * --check compares <dir> against a fresh export and exits 1 naming every
 * file that differs, is missing, or is an extra .php/.json file. The
 * manifest's creed_version is ignored, because it tracks the git checkout.
 *
 * Exit codes:
 *   0  the export was written, or --check found no drift
 *   1  --check found drift (or the export could not write <dir>)
 *   2  bad or missing options
 *   3  the source no longer has the bundled-path expression this export
 *      rewrites, so the export refuses to guess
 */

const GENERATED_HEADER = '// Generated by CREED bin/export.php. Do not edit; re-run the export.';
const BUNDLED_PATH_EXPR = "dirname(__DIR__) . '/policy/policy.json'";
const BUNDLED_PATH_REPLACEMENT = "__DIR__ . '/policy.json'";
const NAMESPACE_PATTERN = '/^[A-Z][A-Za-z0-9]*(\\\\[A-Z][A-Za-z0-9]*)+$/';

/**
 * Print the usage line and exit 2.
 */
function usage(): never
{
    fwrite(STDERR, "Usage: php bin/export.php [--check] --namespace=<ns> --to=<dir>\n");
    fwrite(STDERR, "  --namespace=<ns>  target namespace, e.g. Waynestate\\Proctor\\Creed\n");
    fwrite(STDERR, "  --to=<dir>        directory to write (or check) the copy into\n");
    fwrite(STDERR, "  --check           verify the copy matches a fresh export; creed_version is ignored\n");
    exit(2);
}

/**
 * Print an error and exit 3: the source changed under this export.
 */
function sourceChanged(string $message): never
{
    fwrite(STDERR, 'export failed: ' . $message . "\n");
    exit(3);
}

/**
 * Read a source file, or exit 3 when it cannot be read.
 */
function readSource(string $path): string
{
    $raw = file_get_contents($path);
    if ($raw === false) {
        sourceChanged("cannot read source file: {$path}");
    }

    return $raw;
}

/**
 * Rewrite one reader source file for the target namespace: add the generated
 * header as the first line after <?php, point the namespace declaration and
 * every Waynestate\Creed\ reference at the target, and (for Policy.php)
 * repoint bundled() at the copy's own policy.json. Nothing else changes.
 */
function transformForNamespace(string $source, string $namespace, bool $isPolicy): string
{
    if (!str_starts_with($source, "<?php\n")) {
        sourceChanged('the source file does not start with <?php');
    }
    $source = "<?php\n" . GENERATED_HEADER . "\n" . substr($source, strlen("<?php\n"));

    // One pass over the namespace declaration (followed by ;) and every
    // Waynestate\Creed\ reference (followed by \). A single pass means the
    // replacement text is never re-scanned, so a target namespace that
    // itself contains Waynestate\Creed cannot be corrupted.
    $rewritten = preg_replace_callback(
        '/Waynestate\\\\Creed(?=[;\\\\])/',
        static fn(array $matches): string => $namespace,
        $source,
    );
    if ($rewritten === null) {
        sourceChanged('the namespace rewrite failed');
    }
    $source = $rewritten;

    if ($isPolicy) {
        // The copy sits next to its own policy.json, so bundled() must stop
        // reaching up to the CREED checkout. This is an exact string
        // replacement on purpose: if the source ever changes this line, the
        // export fails instead of shipping a copy that reads the wrong file.
        if (!str_contains($source, BUNDLED_PATH_EXPR)) {
            sourceChanged(
                "the bundled-path expression " . BUNDLED_PATH_EXPR
                . ' was not found in Policy.php; the source changed and this export no longer applies',
            );
        }
        $source = str_replace(BUNDLED_PATH_EXPR, BUNDLED_PATH_REPLACEMENT, $source);
    }

    return $source;
}

/**
 * The CREED version for the manifest: git describe --always in the CREED
 * checkout, or 'unknown' when git is unavailable or the command fails.
 */
function creedVersion(string $root): string
{
    $descriptors = [
        0 => ['pipe', 'r'],
        1 => ['pipe', 'w'],
        2 => ['pipe', 'w'],
    ];
    $pipes = [];
    $process = @proc_open(['git', 'describe', '--always'], $descriptors, $pipes, $root);
    if (!is_resource($process)) {
        return 'unknown';
    }
    fclose($pipes[0]);
    $out = trim((string) stream_get_contents($pipes[1]));
    fclose($pipes[1]);
    fclose($pipes[2]);
    $exit = proc_close($process);

    return $exit === 0 && $out !== '' ? $out : 'unknown';
}

/**
 * The manifest bytes: pretty-printed, keys in the documented order, with a
 * trailing newline.
 *
 * @param array<string, array{sha256: string}> $files
 */
function manifestBytes(array $files, string $namespace, string $creedVersion): string
{
    $manifest = [
        'schema_version' => 1,
        'source' => 'creed',
        'creed_version' => $creedVersion,
        'namespace' => $namespace,
        'files' => $files,
    ];
    $encoded = json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
    if ($encoded === false) {
        sourceChanged('the manifest could not be encoded');
    }

    return $encoded . "\n";
}

/**
 * The sha256 of every file the export writes, keyed by file name.
 *
 * @return array<string, array{sha256: string}>
 */
function fileHashes(string $policyOut, string $stateOut, string $policyJson): array
{
    return [
        'Policy.php' => ['sha256' => hash('sha256', $policyOut)],
        'State.php' => ['sha256' => hash('sha256', $stateOut)],
        'policy.json' => ['sha256' => hash('sha256', $policyJson)],
    ];
}

/**
 * Write the export into $to. Returns the process exit code.
 */
function runExport(string $to, string $namespace, string $policyOut, string $stateOut, string $policyJson, string $root): int
{
    if (!is_dir($to) && !mkdir($to, 0777, true) && !is_dir($to)) {
        fwrite(STDERR, "cannot create directory: {$to}\n");

        return 1;
    }
    $files = [
        'Policy.php' => $policyOut,
        'State.php' => $stateOut,
        'policy.json' => $policyJson,
        'manifest.json' => manifestBytes(fileHashes($policyOut, $stateOut, $policyJson), $namespace, creedVersion($root)),
    ];
    foreach ($files as $name => $content) {
        if (file_put_contents($to . '/' . $name, $content) === false) {
            fwrite(STDERR, "cannot write {$name} into: {$to}\n");

            return 1;
        }
    }

    echo "Exported the CREED reader as {$namespace} to {$to}\n";

    return 0;
}

/**
 * Compare $to against a fresh export. Returns the process exit code: 0 when
 * everything matches (creed_version ignored), 1 naming every problem.
 */
function runCheck(string $to, string $namespace, string $policyOut, string $stateOut, string $policyJson): int
{
    $problems = [];

    if (!is_dir($to)) {
        foreach (['Policy.php', 'State.php', 'policy.json', 'manifest.json'] as $name) {
            $problems[] = $name . ' (missing)';
        }
        reportProblems($problems);

        return 1;
    }

    $expected = [
        'Policy.php' => $policyOut,
        'State.php' => $stateOut,
        'policy.json' => $policyJson,
    ];
    foreach ($expected as $name => $content) {
        $path = $to . '/' . $name;
        if (!is_file($path)) {
            $problems[] = $name . ' (missing)';
            continue;
        }
        if (file_get_contents($path) !== $content) {
            $problems[] = $name . ' (differs)';
        }
    }

    // manifest.json: everything must match except creed_version, which
    // tracks the git checkout the export ran in.
    $manifestPath = $to . '/manifest.json';
    if (!is_file($manifestPath)) {
        $problems[] = 'manifest.json (missing)';
    } else {
        $actual = json_decode((string) file_get_contents($manifestPath), true);
        if (!is_array($actual)) {
            $problems[] = 'manifest.json (invalid JSON)';
        } else {
            unset($actual['creed_version']);
            $expectedManifest = [
                'schema_version' => 1,
                'source' => 'creed',
                'namespace' => $namespace,
                'files' => fileHashes($policyOut, $stateOut, $policyJson),
            ];
            if ($actual !== $expectedManifest) {
                $problems[] = 'manifest.json (differs)';
            }
        }
    }

    // Anything else .php or .json in the directory is not part of the export.
    $expectedNames = ['Policy.php', 'State.php', 'policy.json', 'manifest.json'];
    foreach (scandir($to) ?: [] as $entry) {
        if ($entry === '.' || $entry === '..' || !is_file($to . '/' . $entry)) {
            continue;
        }
        $ext = strtolower(pathinfo($entry, PATHINFO_EXTENSION));
        if (($ext === 'php' || $ext === 'json') && !in_array($entry, $expectedNames, true)) {
            $problems[] = $entry . ' (extra)';
        }
    }

    reportProblems($problems);

    return $problems === [] ? 0 : 1;
}

/**
 * Print each problem on its own line, or the all-clear.
 *
 * @param list<string> $problems
 */
function reportProblems(array $problems): void
{
    if ($problems === []) {
        echo "The export is up to date.\n";

        return;
    }
    foreach ($problems as $problem) {
        fwrite(STDERR, $problem . "\n");
    }
}

/**
 * Parse the command line, or exit 2.
 *
 * @param list<string> $argv
 *
 * @return array{namespace: string, to: string, check: bool}
 */
function parseArgs(array $argv): array
{
    $namespace = null;
    $to = null;
    $check = false;

    foreach (array_slice($argv, 1) as $arg) {
        if (str_starts_with($arg, '--namespace=')) {
            $namespace = substr($arg, strlen('--namespace='));
        } elseif (str_starts_with($arg, '--to=')) {
            $to = substr($arg, strlen('--to='));
        } elseif ($arg === '--check') {
            $check = true;
        } else {
            usage();
        }
    }

    if ($namespace === null || $to === null || !preg_match(NAMESPACE_PATTERN, $namespace)) {
        usage();
    }

    return ['namespace' => $namespace, 'to' => $to, 'check' => $check];
}

/**
 * @param list<string> $argv
 */
function main(array $argv): int
{
    ['namespace' => $namespace, 'to' => $to, 'check' => $check] = parseArgs($argv);

    $root = dirname(__DIR__);
    $policyOut = transformForNamespace(readSource($root . '/src/Policy.php'), $namespace, true);
    $stateOut = transformForNamespace(readSource($root . '/src/State.php'), $namespace, false);
    $policyJson = readSource($root . '/policy/policy.json');

    return $check
        ? runCheck($to, $namespace, $policyOut, $stateOut, $policyJson)
        : runExport($to, $namespace, $policyOut, $stateOut, $policyJson, $root);
}

$argv = $_SERVER['argv'] ?? [];
exit(main($argv));
